-- 2024.02.21

DELIMITER $$
CREATE DEFINER=`root`@`%` PROCEDURE `sport_update`(IN `contest_id` INT(11))
BEGIN
DECLARE ce_id INT(11);
DECLARE done INT DEFAULT FALSE;

	DECLARE cur CURSOR FOR 
    SELECT id FROM vespa_constest_events vce
    WHERE vce.contest_id=contest_id;
DECLARE CONTINUE HANDLER FOR NOT FOUND SET done = 1;    
	
    -- open the cursor
	OPEN cur;
	   
	
    process: LOOP
		
        FETCH cur INTO ce_id;      		
           IF done = 1 THEN
             LEAVE process;
            END IF;
        		
        UPDATE vespa_constest_events vce
        SET sport_id=
        (SELECT se.sport_id 
        FROM `vespa_sport_events` se
        JOIN vespa_constest_events ce ON  se.sport_event_id=ce.event_id AND ce.id=ce_id
        WHERE ce.contest_id=contest_id)
        WHERE vce.contest_id=contest_id;
       
        
	END LOOP;
    
    
	CLOSE cur;

END$$
DELIMITER ;

DELIMITER $$
CREATE DEFINER=`root`@`%` PROCEDURE `ahtlete_entries_update`(IN `contest_id` INT)
BEGIN
DECLARE ae_id INT(11);
DECLARE done INT DEFAULT FALSE;

	DECLARE cur CURSOR FOR 
    SELECT id
    FROM vespa_athlete_entries vae
    WHERE vae.contest_id=contest_id;
DECLARE CONTINUE HANDLER FOR NOT FOUND SET done = 1;    
	
    -- open the cursor
	OPEN cur;
	   
	
    process: LOOP
		
        FETCH cur INTO ae_id;      		
           IF done = 1 THEN
             LEAVE process;
            END IF;
        		
        UPDATE vespa_athlete_entries vae
        SET vae.contest_event_id=
        (SELECT ce.id
         FROM vespa_athlete_entries ae
         JOIN vespa_constest_events ce ON  ae.event_id=ce.event_id AND ae.contest_id=ce.contest_id
         JOIN vespa_athletes a ON a.athlete_id=ae.athlete_id
         WHERE FIND_IN_SET (a.disability_type,ce.disability_groups)
         AND a.birth_date>=ce.dfrom AND a.birth_date<=ce.dto AND ae.id=ae_id
         ORDER BY ce.id LIMIT 1)
        WHERE vae.contest_id=contest_id AND  vae.id=ae_id;
       
        
	END LOOP;
    
    
	CLOSE cur;

END$$
DELIMITER ;


